alter table public.race_events
  add column if not exists climb_pct smallint not null default 14,
  add column if not exists rolling_pct smallint not null default 86,
  add column if not exists sprint_pct smallint not null default 0,
  add column if not exists sprint_finish boolean not null default false,
  add column if not exists profile_source text not null default 'Estimation automatique',
  add column if not exists key_points jsonb not null default '[]'::jsonb;

alter table public.rider_scores
  add column if not exists mountain smallint not null default 40 check (mountain between 1 and 100),
  add column if not exists sprint smallint not null default 40 check (sprint between 1 and 100),
  add column if not exists rouleur smallint not null default 40 check (rouleur between 1 and 100);

alter table public.race_events
  add constraint race_events_profile_percentages_check check (
    climb_pct between 0 and 100
    and rolling_pct between 0 and 100
    and sprint_pct between 0 and 100
    and climb_pct + rolling_pct + sprint_pct = 100
    and sprint_finish = (sprint_pct > 0)
    and jsonb_typeof(key_points) = 'array'
  );

on conflict (rider_id) do update set
  rider_name = excluded.rider_name,
  score = excluded.score,
  profile = excluded.profile,
  mountain = excluded.mountain,
  sprint = excluded.sprint,
  rouleur = excluded.rouleur;

on conflict (slug) do update set
  name = excluded.name,
  race_date = excluded.race_date,
  country = excluded.country,
  climb_pct = excluded.climb_pct,
  rolling_pct = excluded.rolling_pct,
  sprint_pct = excluded.sprint_pct,
  sprint_finish = excluded.sprint_finish,
  profile_source = excluded.profile_source,
  key_points = excluded.key_points;

create or replace function public.score_race_team(p_race_date date, p_rider_ids text[])
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_score integer;
  v_count integer;
begin
  select count(*), coalesce(sum(round((
    scores.mountain * events.climb_pct
    + scores.rouleur * events.rolling_pct
    + scores.sprint * events.sprint_pct
  )::numeric / 100)), 0)::integer
    into v_count, v_score
    from public.daily_races as daily
    join public.race_events as events on events.slug = daily.race_slug
    cross join unnest(p_rider_ids) as submitted(rider_id)
    join public.rider_scores as scores using (rider_id)
    where daily.race_date = p_race_date;
  if v_count <> 5 then
    raise exception 'Impossible de calculer le score de cette équipe ou de son parcours.';
  end if;
  return v_score;
end;
$$;

create or replace function public.register_race_team(p_race_date date, p_rider_ids text[])
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_today date := timezone('Europe/Paris', now())::date;
  v_race public.daily_races%rowtype;
  v_collection jsonb;
  v_owned_count integer;
  v_score_count integer;
  v_score integer;
  v_display_name text;
  v_opens timestamptz;
  v_closes timestamptz;
begin
  if v_user_id is null then
    raise exception 'Connecte-toi pour inscrire une équipe.';
  end if;
  if p_rider_ids is null or cardinality(p_rider_ids) <> 5
     or (select count(distinct rider_id) from unnest(p_rider_ids) as submitted(rider_id)) <> 5
     or exists (select 1 from unnest(p_rider_ids) as submitted(rider_id)
                where rider_id is null or length(rider_id) > 160) then
    raise exception 'Une équipe doit contenir exactement 5 cartes distinctes.';
  end if;
  if p_race_date is distinct from v_today then
    raise exception 'Seule la course du jour accepte les inscriptions.';
  end if;
  select * into v_race from public.daily_races where daily_races.race_date = p_race_date;
  if not found then
    raise exception 'La course du jour n’est pas encore sélectionnée.';
  end if;
  v_opens := (p_race_date + time '00:00') at time zone 'Europe/Paris';
  v_closes := (p_race_date + time '19:55') at time zone 'Europe/Paris';
  if now() < v_opens or now() >= v_closes then
    raise exception 'Les inscriptions sont ouvertes de 0 h à 19 h 55, heure de Paris, le jour de la course.';
  end if;
  select payload into v_collection from public.user_collections
    where user_id = v_user_id for update;
  if not found then
    raise exception 'Ta collection doit être synchronisée avant l’inscription.';
  end if;
  select count(*) into v_owned_count
    from unnest(p_rider_ids) as submitted(rider_id)
    where coalesce(v_collection->'riders', '{}'::jsonb) ? submitted.rider_id;
  if v_owned_count <> 5 then
    raise exception 'Tu ne possèdes pas toutes les cartes sélectionnées.';
  end if;
  select count(scores.rider_id) into v_score_count
    from unnest(p_rider_ids) as submitted(rider_id)
    left join public.rider_scores as scores using (rider_id);
  if v_score_count <> 5 then
    raise exception 'Impossible de vérifier le score de cette équipe.';
  end if;
  v_score := public.score_race_team(p_race_date, p_rider_ids);
  select coalesce(username, 'Cycliste') into v_display_name
    from public.profiles where user_id = v_user_id;
  v_display_name := coalesce(v_display_name, 'Cycliste');
    values (p_race_date, v_user_id, v_display_name, p_rider_ids, v_score, now())
    on conflict (race_date, user_id) do update
      set display_name = excluded.display_name, rider_ids = excluded.rider_ids,
          score = excluded.score, updated_at = excluded.updated_at;
end;
$$;

revoke all on function public.score_race_team(date, text[]) from public, anon, authenticated;
revoke all on function public.register_race_team(date, text[]) from public, anon, authenticated;
grant execute on function public.register_race_team(date, text[]) to authenticated;

update public.race_entries as entries
set score = public.score_race_team(entries.race_date, entries.rider_ids);
